INSERT INTO `informations` VALUES (12,'Jdas 2026','Le club scientifique du LMDB est pré-sélectionné pour competir.','info_69419d2ef23ac.jpg','','2025-12-16 18:55:58'),(13,'Jdas 2026','Le club scientifique se prépare ','info_6942b9c6b7844.jpg','','2025-12-17 15:10:14'),(15,'Communiqué du club scientifique LMDB','🗣informations ','info_69450a95d76f4.jpg','','2025-12-19 09:19:33'),(16,'Informations','chers membres du club remplissez ce formulaire en fin de nous aider pour le bon deroulement des activites\r\nhttps://forms.gle/i1CGdLX7fyXBTdjo6\r\nmerci de votre comprhension',NULL,'','2026-01-01 16:37:04'),(17,'Information','Nous informons tous les membres déjà inscrits que la création des cartes de membres est en cours.\r\n\r\nVos cartes seront bientôt disponibles. Vous serez informés dès qu’elles pourront être récupérées.\r\n\r\nMerci pour votre patience et votre engagement.',NULL,'','2026-01-14 21:26:38'),(18,'Votre attention ⚠️','Informations ℹ️ \r\non a oublié de mettre l\'heur c\'est a 12h','info_696a55fc9cbfd.jpg','','2026-01-16 16:15:08'),(19,'Les Cartes de membres','Les cartes de membres seront disponibles à partir de ce mardi. Vous pourrez les récupérer auprès du trésorier, en salle 1.\r\nPOUR CEUX QUI ON DONNE LES 500F','info_696d78c7bb3eb.jpg','','2026-01-19 01:20:23'),(20,'urgent','Compte tenu de l’emploi du temps chargé des membres et de l’impossibilité de tenir la réunion le matin, nous vous informons que la réunion est reportée jusqu’à nouvel ordre. Merci pour votre compréhension.\r\nmerci d\'informer les autres.',NULL,'','2026-01-23 22:35:29'),(21,'urgent','Compte tenu de l’emploi du temps chargé des membres et de l’impossibilité de tenir la réunion le matin, nous vous informons que la réunion est reportée jusqu’à nouvel ordre. Merci pour votre compréhension.\r\nmerci d\'informer les autres.',NULL,'','2026-01-23 22:43:01'),(22,'urgent','Ensemble, nous sommes plus forts et nos idées ont plus d’impact.\r\nLe succès du groupe dépend de l’engagement de chacun.','info_6977d74c646d0.jpg','','2026-01-26 22:06:20'),(23,'📢 Début des activités','📢 Début des activités\r\nAprès échange avec les coordonnateurs du Club Multimédia, nous avons reçu la confirmation qu’à partir de lundi, la salle Multimédia sera ouverte, les ordinateurs seront disponibles, et les activités pourront officiellement commencer.\r\nCependant, les cours reprenant à 12h30, l’organisation se fera comme suit :\r\n🗓 Jour : Lundi 9 février\r\n⏰ Heure de travail : 12h00 à 12h30\r\n📚 À 12h30, tout le monde devra retourner en classe.\r\n💻 Les ordinateurs seront disponibles pour le travail durant ce créneau.\r\nMerci de bien vouloir confirmer votre présence et de faire preuve de ponctualité, afin de démarrer dans de bonnes conditions.\r\nNous comptons sur le sérieux et l’engagement de chacun. 💪','info_6983376830188.jpg','','2026-02-04 13:11:20'),(27,'📢 Début des activités','📢 Début des activités\r\nAprès échange avec les coordonnateurs du Club Multimédia, nous avons reçu la confirmation qu’à partir de lundi, la salle Multimédia sera ouverte, les ordinateurs seront disponibles, et les activités pourront officiellement commencer.\r\nCependant, les cours reprenant à 12h30, l’organisation se fera comme suit :\r\n🗓 Jour : Lundi 9 février\r\n⏰ Heure de travail : 12h00 à 12h30\r\n📚 À 12h30, tout le monde devra retourner en classe.\r\n💻 Les ordinateurs seront disponibles pour le travail durant ce créneau.\r\nMerci de bien vouloir confirmer votre présence et de faire preuve de ponctualité, afin de démarrer dans de bonnes conditions.\r\nNous comptons sur le sérieux et l’engagement de chacun. 💪','info_698339a25b660.jpg','','2026-02-04 13:20:50'),(28,'urgent','https://cslmdb.cybibff.site/\r\n','info_6984b66ef26df.jpg','','2026-02-05 16:25:35'),(29,'📢 Début des activités','Nous informons tous les membres que l’activité prévue aujourd’hui à la salle informatique est reportée.\r\n\r\nCette décision a été prise en raison de la tenue d’un match de Génie en Herbe dans la salle informatique au même moment. La salle étant occupée pour cette activité académique, nous ne pourrons pas y travailler comme prévu.\r\n\r\n👉 L’activité est donc reportée à mercredi à la même heure.\r\n\r\nMerci pour votre compréhension et votre collaboration.',NULL,'','2026-02-09 14:33:32'),(30,'On vous donne rendez-vous demain à la salle informatique','L’activité prévue lundi n’a pas pu se tenir car la salle informatique était occupée pour une autre activité scolaire au même moment. L’espace n’étant pas disponible, il n’était pas possible de travailler dans de bonnes conditions.\r\nC’est pour cette raison que la séance est déplacée au jeudi de 12h00 à 12h30.\r\nMerci pour votre compréhension et votre esprit de collaboration.',NULL,'','2026-02-11 21:18:04'),(31,'On vous donne rendez-vous demain à la salle informatique','L’activité prévue lundi n’a pas pu se tenir car la salle informatique était occupée pour une autre activité scolaire au même moment. L’espace n’étant pas disponible, il n’était pas possible de travailler dans de bonnes conditions.\r\nC’est pour cette raison que la séance est déplacée au jeudi de 12h00 à 12h30.\r\nMerci pour votre compréhension et votre esprit de collaboration.',NULL,'','2026-02-11 21:18:21'),(32,'communique','les activités du club ont déjà commencé ','info_698df131a5c28.jpg','','2026-02-12 16:26:41'),(33,'Début des activités','Notre première activité s’est déroulée avec succès. Merci à tous pour votre engagement 👏🏾\r\n🔹 Pour les absents :\r\nSi vous n’avez pas pu participer, veuillez vous rapprocher du groupe pour la mise à niveau afin de ne pas accumuler de retard.\r\n🔹 Pour ceux qui souhaitent intégrer :\r\nLe groupe reste ouvert aux personnes sérieuses et motivées. Contactez-nous pour connaître les modalités d’adhésion.\r\n📅 Prochaine activité : Mardi\r\n⏰ De 12h00 à 12h30\r\n📍 Salle informatique\r\nSoyons ponctuels et engagés pour continuer sur cette belle lancée 🚀',NULL,'','2026-02-16 15:37:13'),(34,'Début des activités','Notre première activité s’est déroulée avec succès. Merci à tous pour votre engagement 👏🏾\r\n🔹 Pour les absents :\r\nSi vous n’avez pas pu participer, veuillez vous rapprocher du groupe pour la mise à niveau afin de ne pas accumuler de retard.\r\n🔹 Pour ceux qui souhaitent intégrer :\r\nLe groupe reste ouvert aux personnes sérieuses et motivées. Contactez-nous pour connaître les modalités d’adhésion.\r\n📅 Prochaine activité : Mardi\r\n⏰ De 12h00 à 12h30\r\n📍 Salle informatique\r\nSoyons ponctuels et engagés pour continuer sur cette belle lancée 🚀',NULL,'','2026-02-16 15:37:45'),(35,'activités prévu','demain on se donne rendez-vous a 9h \r\n(s\'il y\'a débrayage)\r\n',NULL,'','2026-02-17 22:31:47'),(36,'séance de travail','Chers membres,\r\nDemain à partir de 10h, nous aurons une séance de travail pour faire les réglages nécessaires au bon déroulement de nos prochaines activités.\r\nPour plus de détails 784065300',NULL,'','2026-02-18 20:12:02'),(37,'Inscrivez-vous','Salut à toutes et à tous, chers scientifiques\r\nInscrivez-vous, c’est une très grosse opportunité 🙏🏿https://docs.google.com/forms/d/e/1FAIpQLSfuw0QfatMVS43BQY3_oUyJ8bMoPv20vowDKbX9RSGeKseJeg/viewform','info_699afcaa7388f.jpg','','2026-02-22 13:55:06'),(38,'Inscrivez-vous','Salut à toutes et à tous, chers scientifiques\r\nInscrivez-vous, c’est une très grosse opportunité 🙏🏿https://docs.google.com/forms/d/e/1FAIpQLSfuw0QfatMVS43BQY3_oUyJ8bMoPv20vowDKbX9RSGeKseJeg/viewform','info_699afcd1156b5.jpg','','2026-02-22 13:55:45'),(39,'Préparation JDAS 2026','🔬 CLUB SCIENTIFIQUE LMDB\r\n📅 Demain à 12h00, le club scientifique LMDB organise une activité importante.\r\n🎯  \r\nLe concours AASTIC JDAS 2026 sera au cœur des débats.\r\n📘 Un document explicatif sera présenté afin de permettre aux membres de mieux comprendre :\r\n+Les objectifs du concours\r\n+Les critères de participation\r\n+Les attentes et exigences\r\nLa préparation nécessaire\r\nCette rencontre permettra à chaque membre d’acquérir les connaissances essentielles pour bien se préparer et participer activement.\r\n✨ La présence de tous les membres est vivement souhaitée.',NULL,'','2026-02-22 22:45:40'),(40,'💻 Activité pratique du jour – Club Scientifique LMDB','\r\nAujourd’hui, nos membres ont participé à une séance 100% pratique.\r\n🔧 Montage d’un ordinateur fixe\r\nLes élèves ont appris à assembler les différents composants et à comprendre le fonctionnement interne d’un ordinateur.\r\n🗂️ Création de dossiers\r\nIls ont appris à organiser les fichiers correctement pour un travail structuré et professionnel.\r\n📝 Saisie sur Microsoft Word\r\nLes membres se sont exercés à taper des documents, appliquer une bonne mise en forme et structurer un texte correctement.\r\n🎯 Objectif de la séance :\r\nDévelopper des compétences pratiques\r\nMaîtriser les bases de l’informatique\r\nRenforcer l’autonomie des élèves\r\nAujourd’hui, nous ne faisons pas que regarder…\r\nNous pratiquons, nous apprenons et nous progressons. 🚀\r\nNB: pour les autres séances portons nos cartes de membres. \r\nMerci de votre compréhension. ','info_699cb9199b64c.jpg','','2026-02-23 21:31:21'),(41,'activités prévu','demain on vous donne rendez-vous a 9h',NULL,'','2026-02-24 23:56:45'),(42,'📢 RÉUNION IMPORTANTE – CONCOURS INTERCLUBS SCIENTIFIQUE JDAS 2026','📢 RÉUNION IMPORTANTE – CONCOURS INTERCLUBS SCIENTIFIQUE JDAS 2026\r\nUne réunion sérieuse est organisée pour tous les membres qui souhaitent participer au concours interclubs scientifique JDAS 2026.\r\n🎯 Objectif de la réunion :\r\nExpliquer les critères de participation\r\nFormer les équipes\r\nDéfinir les projets à préparer\r\nMettre en place une stratégie de travail efficace\r\n📅 Date : Lundi\r\n⏰ Heure : 12h00 – 12h30\r\n🔁 Poursuite : 14h30\r\n📍 Lieu : Salle informatique\r\n⚠️ La présence est obligatoire pour tous les membres motivés et déterminés à représenter dignement notre club.\r\n🔥 La réussite se prépare. La victoire s’organise.',NULL,'','2026-02-28 22:49:41'),(43,'📢 RÉUNION IMPORTANTE – CONCOURS INTERCLUBS SCIENTIFIQUE JDAS 2026','📢 RÉUNION IMPORTANTE – CONCOURS INTERCLUBS SCIENTIFIQUE JDAS 2026\r\nUne réunion sérieuse est organisée pour tous les membres qui souhaitent participer au concours interclubs scientifique JDAS 2026.\r\n🎯 Objectif de la réunion :\r\nExpliquer les critères de participation\r\nFormer les équipes\r\nDéfinir les projets à préparer\r\nMettre en place une stratégie de travail efficace\r\n📅 Date : Lundi\r\n⏰ Heure : 12h00 – 12h30\r\n🔁 Poursuite : 14h30\r\n📍 Lieu : Salle informatique\r\n⚠️ La présence est obligatoire pour tous les membres motivés et déterminés à représenter dignement notre club.\r\n🔥 La réussite se prépare. La victoire s’organise.',NULL,'','2026-02-28 22:51:05'),(44,'📢 RÉUNION IMPORTANTE – CONCOURS INTERCLUBS SCIENTIFIQUE JDAS 2026','📢 RÉUNION IMPORTANTE – CONCOURS INTERCLUBS SCIENTIFIQUE JDAS 2026\r\nUne réunion sérieuse est organisée pour tous les membres qui souhaitent participer au concours interclubs scientifique JDAS 2026.\r\n🎯 Objectif de la réunion :\r\nExpliquer les critères de participation\r\nFormer les équipes\r\nDéfinir les projets à préparer\r\nMettre en place une stratégie de travail efficace\r\n📅 Date : Lundi\r\n⏰ Heure : 12h00 – 12h30\r\n🔁 Poursuite : 14h30\r\n📍 Lieu : Salle informatique\r\n⚠️ La présence est obligatoire pour tous les membres motivés et déterminés à représenter dignement notre club.\r\n🔥 La réussite se prépare. La victoire s’organise.\r\nChaqu’un peut choisir le groupe qui l’intéresse. (L’épreuve)',NULL,'','2026-02-28 22:51:09'),(45,'Urgent info','Bonjour à tous, en cas de débrayage demain, nous démarrerons à 9h00. \r\nPasser l’informations ',NULL,'','2026-03-01 23:41:43'),(49,'Groupe WhatsApp pour les membres','Ce groupe est créé pour faciliter la communication et le partage d’informations concernant nos activités scientifiques, les concours , les réunions et les formations.\r\nhttps://chat.whatsapp.com/GoqL18y9pOQ6Z8DQmJuOii?mode=gi_t \r\n\r\ninfo:784065300\r\n','info_69a87abcc1e08.png','','2026-03-04 14:21:03'),(50,'Informations','Report dates formations\r\n\r\nBonsoir Censeur,\r\nEn espérant que ce message vous trouve en bonne santé ! Je vous informe malheureusement pour des raisons indépendantes de notre volonté, la formation des clubs scientifiques pour Sedhiou, Ziguinchor et Kaolack est reportée après les fêtes de Korité. \r\nEn attendant, les élèves peuvent s’inscrire directement sur la plate-forme (https://cle.astic-sn.org) et accéder automatiquement aux contenus.',NULL,'','2026-03-15 23:33:02'),(51,'Préparation JDAS 2026','Les personnes intéressées peuvent contacter les chefs de groupe ','info_69b88812797d9.jpg','','2026-03-16 23:45:38'),(52,'Informations ℹ️','Demain, les personnes disponibles sont invitées à rejoindre M. Niouki à la salle informatique.',NULL,'','2026-03-17 23:46:29'),(53,'Journée Scientifique- JDAS 2026','Le pv de notre dernière réunion \r\nMerci de le lire attentivement .\r\nBesoin d’autre information vous pouvez contacter un des responsables. \r\nMerci ','info_69bbeddae6e3c.jpg','','2026-03-19 13:36:42'),(54,'Journée Scientifique- JDAS 2026','Le pv de notre dernière réunion \r\nMerci de le lire attentivement .\r\nBesoin d’autre information vous pouvez contacter un des responsables. \r\nMerci ','info_69bbee2615dc0.jpg','','2026-03-19 13:37:58'),(55,'Journée Scientifique- JDAS 2026','Le pv de notre dernière réunion \r\nMerci de le lire attentivement .\r\nBesoin d’autre information vous pouvez contacter un des responsables. \r\nMerci ','info_69bbee4ebce68.jpg','','2026-03-19 13:38:38'),(56,'Journée Scientifique &amp;JDAS 2026','Le pv de notre dernière réunion \r\nMerci de le lire attentivement .\r\nBesoin d’autre information vous pouvez contacter un des responsables. \r\nMerci ','info_69bbee614c109.jpg','','2026-03-19 13:38:57'),(57,'Une réunion est prévue demain à 11h sur Google Meet','Bonsoir à tous,\r\nUne réunion est prévue demain à 11h sur Google Meet. Elle portera sur l’organisation de la journée du club (déroulement, programme et autres points essentiels), ainsi que sur le JDAS 2026.\r\nhttps://meet.google.com/dxi-dihy-gsg\r\n',NULL,'','2026-03-20 02:13:17'),(58,'Tournée de formation','Aastic sera la le  vendredi 27 mars à 10h30 pour une formation a l’occasion de la préparation du concours JDAS 2026.','info_69c1416f799a4.jpg','','2026-03-23 14:34:39'),(59,'Tournée de formation AASTIC JDAS 2026','Merci de venir avec vos cartes de membres si possible. ','info_69c2cab53655e.jpg','','2026-03-24 18:31:08'),(60,'📢 RÉUNION IMPORTANTE – CONCOURS INTERCLUBS SCIENTIFIQUE JDAS 2026','Les membres du club sont autorisés de participer à la formation. ','info_69c54ee463d94.jpg','','2026-03-26 16:21:08'),(61,'📢 RÉUNION IMPORTANTE – CONCOURS INTERCLUBS SCIENTIFIQUE JDAS 2026','Les membres du club sont autorisés de participer à la formation. ','info_69c54f1f76afd.jpg','','2026-03-26 16:22:07'),(62,'Procès verbale de la formation','Tournée de formation organisée par AASTIC Sénégal ','info_69c949dea7059.jpg','','2026-03-29 17:48:46'),(63,'Séances de formation pour préparer le JDAS_2026','La commission pédagogique ','info_69ced14a36857.png','','2026-04-02 22:27:54'),(64,'Bonne fête à toutes et à tous ! 🎉🇸🇳','🇸🇳 Le Club Scientifique du Lycée Maba Diakhou Ba souhaite à toute la communauté éducative ainsi qu’à l’ensemble du peuple sénégalais une excellente fête de l’Indépendance !\r\nEn ce jour mémorable du , célébrons avec fierté notre histoire, nos valeurs et notre engagement pour un avenir meilleur à travers la science, l’innovation et le savoir.\r\nBonne fête à toutes et à tous ! 🎉🇸🇳',NULL,'','2026-04-04 12:41:44'),(65,'Chers membres du club,','on ne peut pas représenter dignement le club scientifique si l\'on ne participe pas aux séances de renforcement de capacités.\r\nAbsences non justifiées, elles témoignent d\'un manque d\'engagement. Pour un concours de cette envergure, le club a besoin de membres sur qui on peut compter.\r\nDes mesures fermes seront prises. ',NULL,'','2026-04-06 18:56:44'),(66,'Réunion de finalisation des préparatifs des jdas','🚨Présence obligatoire ','info_69db60ec1cb02.png','','2026-04-12 11:07:56'),(67,'Information importante – Concours JDAS 2026','Chers membres du club,\r\n\r\nNous vous informons que la phase régionale du concours JDAS 2026 se tiendra le samedi 18 avril à Kaolack, au Lycée Valdiodio Ndiaye, de 15h à 18h.\r\n\r\n👥 Groupes concernés :\r\n\r\n- Binôme 1 : QCM Math-PC-SVT\r\n- Binôme 2 : Math-Info (GeoGebra)\r\n- Binôme 3 : Codage (HTML & CSS)\r\n- Binôme 4 : Culture numérique\r\n\r\nMerci de bien vouloir vous préparer en conséquence et être présents à l’heure.\r\nLa participation et le sérieux de chacun sont essentiels.\r\n\r\nBonne chance à tous ! ','info_69e011ca1bc34.png','','2026-04-16 00:21:42'),(68,'Phase régionale','Phase régionale des JDAS ','info_69e6377cb7f9f.jpg','','2026-04-20 16:26:04'),(69,'Félicitations','Félicitations ',NULL,'','2026-04-22 17:34:14'),(70,'urgent','information','info_69eb868f773b4.png','','2026-04-24 17:04:47'),(71,'urgent','information','info_69eb86d3d3470.png','','2026-04-24 17:05:55'),(72,'page facebook du club','https://www.facebook.com/share/1AxyTv8J4E/\r\nveillez suivre notre page',NULL,'','2026-04-24 17:36:43'),(73,'📢 Avis aux candidats','📢 Avis aux candidats\r\n\r\nUne rencontre est prévue demain à 16h dans la salle informatique.\r\nLa présence de tous les candidats est obligatoire.\r\n\r\nVeuillez venir avec le matériel nécessaire pour chaque groupe.',NULL,'','2026-04-27 23:14:49'),(74,'Chers membres','Bonjour chers membres du club scientifique,\r\n\r\nNous vous informons que le reste des médailles de la 10ᵉ édition du JDAS a enfin été reçu. 🏅\r\n\r\nSont concernés : SVT pratique, Codage et SIG.\r\nDésormais, chaque membre des binômes concernés recevra sa propre médaille, soit 2 médailles par binôme.\r\n\r\nMerci pour votre patience et félicitations encore à tous les lauréats. 🎉','info_6a154909e8f13.png','','2026-05-26 09:17:29'),(75,'Bonne chance aux candidats du BFEM','Bonne chance ','info_6a5553ea4ca25.png','','2026-07-13 23:08:58'),(81,'Hommage à Maba Diakhou Ba','Hommage à MABA DIAKHOU BA ','info_6a5c1ac406254.jpg','','2026-07-19 02:23:24'),(82,'𝗔𝗽𝗽𝗲𝗹 à 𝗰𝗮𝗻𝗱𝗶𝗱𝗮𝘁𝘂𝗿𝗲𝘀','𝗔𝗽𝗽𝗲𝗹 𝗮̀ 𝗰𝗮𝗻𝗱𝗶𝗱𝗮𝘁𝘂𝗿𝗲𝘀 : 𝗽𝗮𝗿𝗰𝗼𝘂𝗿𝘀 𝗨𝗫/𝗨𝗜 𝗲𝘁 𝗜𝗻𝗴𝗲́𝗻𝗶𝗲𝗿𝗶𝗲 𝗹𝗼𝗴𝗶𝗰𝗶𝗲𝗹𝗹𝗲\r\n\r\nLe programme  Force-N Sénégal, mis en œuvre par l’Université numérique Cheikh Hamidou KANE - Un-Chk en partenariat avec la Mastercard Foundation lance un appel à candidatures pour des formations certifiantes gratuites, destinées aux jeunes de moins de 36 ans souhaitant développer leurs compétences dans les métiers du numérique.\r\n\r\n●𝗖𝗲𝗿𝘁𝗶𝗳𝗶𝗰𝗮𝘁𝗶𝗼𝗻𝘀 𝗱𝗶𝘀𝗽𝗼𝗻𝗶𝗯𝗹𝗲𝘀 :\r\n\r\n🔹 Développement logiciel (Java, PHP, Python)\r\n🔹 Développement Front-end et mobile\r\n🔹 Low Code / No Code\r\n🔹 UX/UI Design\r\n\r\n■ Postulez dès maintenant via : https://lc.cx/SIG2608\r\n\r\n● Clôture des candidatures : dimanche 13 septembre 2026 à 23h59 GMT\r\n\r\n𝗟𝗲𝘀 𝗰𝗮𝗻𝗱𝗶𝗱𝗮𝘁𝘂𝗿𝗲𝘀 𝗳𝗲́𝗺𝗶𝗻𝗶𝗻𝗲𝘀 𝘀𝗼𝗻𝘁 𝗳𝗼𝗿𝘁𝗲𝗺𝗲𝗻𝘁 𝗲𝗻𝗰𝗼𝘂𝗿𝗮𝗴𝗲́𝗲𝘀.\r\n\r\n#Forcen #UNCHK_Sn #MastercardFoundation #candidature #formationprofessionnelle #formationenligne #devlogiciel #uxuidesign','info_6a95b4c71f225.jpg','','2026-08-31 19:07:19');
/*!40000 ALTER TABLE `informations` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `membres`
--

DROP TABLE IF EXISTS `membres`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `membres` (
  `id` int NOT NULL AUTO_INCREMENT,
  `nom` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `prenom` varchar(50) COLLATE utf8mb4_general_ci NOT NULL,
  `email` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `telephone` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `classe` enum('Seconde','Premiere','Terminal','Superieur') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `serie` enum('S','S1','S2','Autre') COLLATE utf8mb4_general_ci NOT NULL,
  `mot_de_passe` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
