INSERT INTO `projets` VALUES (2,'projet de l&#039;année','📌 Réunion du Club Scientifique – CSLMDB\r\nCe mardi 27 janvier 2026 à 16h30, le Club Scientifique du Lycée Maba Diakhou Bâ a tenu une réunion de planification axée sur l’organisation des activités du club et la préparation stratégique de la JDAS 2026.\r\nLes échanges ont porté sur : 🔹 Le renforcement des projets scientifiques et numériques\r\n🔹 Les futures activités et démonstrations pratiques\r\n🔹 La participation aux concours scientifiques\r\n🔹 L’anticipation des épreuves de la JDAS (Maths, PC, SVT, Codage, SIG…)\r\nLe club poursuit son engagement pour développer l’esprit scientifique, les compétences numériques et la culture technologique chez les élèves.\r\n🚀 La science en action, l’avenir en préparation !\r\n#ClubScientifique #CSLMDB #JDAS2026 #Science #Innovation #Éducation','2026-01-27');
